from dataclasses import dataclass
from fastapi import FastAPI, Request
from fastapi.exceptions import RequestValidationError
from fastapi.responses import JSONResponse
from pydantic import ValidationError

@dataclass
class AppError(Exception):
    code: str
    message: str
    status_code: int = 400
    details: dict | None = None

class NotFoundError(AppError):
    def __init__(self, resource: str, id: str):
        super().__init__('not_found', f'{resource} not found', 404, {'id': id})

app = FastAPI()

@app.exception_handler(AppError)
async def app_error_handler(request: Request, exc: AppError) -> JSONResponse:
    rid = request.headers.get('x-request-id')
    # log.warning('app_error', code=exc.code, request_id=rid)
    return JSONResponse(
        status_code=exc.status_code,
        content={'error': {'code': exc.code, 'message': exc.message, 'details': exc.details, 'request_id': rid}},
    )

@app.exception_handler(RequestValidationError)
async def validation_handler(request: Request, exc: RequestValidationError) -> JSONResponse:
    rid = request.headers.get('x-request-id')
    # strip input values if sensitive
    safe = [{'loc': e.get('loc'), 'type': e.get('type'), 'msg': e.get('msg')} for e in exc.errors()]
    return JSONResponse(status_code=422, content={'error': {'code': 'validation_error', 'message': 'Invalid request', 'details': safe, 'request_id': rid}})

@app.exception_handler(Exception)
async def unhandled(request: Request, exc: Exception) -> JSONResponse:
    rid = request.headers.get('x-request-id')
    # log.exception('unhandled', request_id=rid)
    return JSONResponse(status_code=500, content={'error': {'code': 'internal_error', 'message': 'Internal server error', 'request_id': rid}})

# Optional Result for pure boundary
from typing import TypeVar, Generic, Union
T = TypeVar('T')
E = TypeVar('E')
@dataclass(frozen=True)
class Ok(Generic[T]):
    value: T
@dataclass(frozen=True)
class Err(Generic[E]):
    error: E
Result = Union[Ok[T], Err[E]]
